-- P29: Reward Studio records (Doc 06 §1.4, Doc 09 §6.3 Rewards).
-- A reward definition holds versions. A version's content (policy, code bundle, hash inputs,
-- test cases) never changes once written; only its lifecycle state and test results do, and
-- once PUBLISHED only the step to DEPRECATED is left. Triggers enforce both.

-- Components the server knows (built-ins of mrl-rewards, generated by tools/gen/rewards.py
-- and upserted at startup). Platform-wide: no org.
CREATE TABLE reward_components (
  ref text PRIMARY KEY CHECK (ref ~ '^builtin/[a-z0-9][a-z0-9._-]*@[0-9]+$'),
  version text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('builtin', 'code_exec')),
  tier smallint NOT NULL CHECK (tier IN (1, 2)),
  shape text NOT NULL,
  deterministic boolean NOT NULL,
  stateful boolean NOT NULL,
  beta boolean NOT NULL,
  value_min double precision NOT NULL,
  value_max double precision NOT NULL,
  needs text[] NOT NULL DEFAULT '{}',
  description text NOT NULL,
  param_schema jsonb NOT NULL,
  code_sha256 text NOT NULL CHECK (code_sha256 ~ '^[0-9a-f]{64}$'),
  listed boolean NOT NULL DEFAULT true,            -- false: no longer shipped by this server
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE reward_definitions (
  id uuid PRIMARY KEY,
  org_id uuid NOT NULL,
  project_id uuid NOT NULL,
  name text NOT NULL CHECK (name ~ '^[a-z0-9]([a-z0-9._-]{0,98}[a-z0-9])?$'),
  description text NOT NULL DEFAULT '' CHECK (char_length(description) <= 2000),
  next_version integer NOT NULL DEFAULT 1 CHECK (next_version >= 1),
  created_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT reward_definitions_name UNIQUE (org_id, project_id, name)
);
CREATE INDEX reward_definitions_project ON reward_definitions (org_id, project_id, id);

CREATE TABLE reward_versions (
  id uuid PRIMARY KEY,
  org_id uuid NOT NULL,
  project_id uuid NOT NULL,
  reward_id uuid NOT NULL REFERENCES reward_definitions(id),
  version_no integer NOT NULL CHECK (version_no >= 1),
  state text NOT NULL CHECK (state IN ('DRAFT', 'TESTING', 'PUBLISHED', 'FAILED_TESTS', 'DEPRECATED')),
  state_version bigint NOT NULL DEFAULT 1,         -- outbox seq of the version's events
  policy jsonb NOT NULL,                           -- RewardPolicy v1, as validated
  content_sha256 text NOT NULL CHECK (content_sha256 ~ '^[0-9a-f]{64}$'),
  hash_inputs jsonb NOT NULL,                      -- exactly what content_sha256 covers
  sandbox_tier text NOT NULL CHECK (sandbox_tier IN ('standard', 'code_exec')),
  code_artifact_id uuid NULL,                      -- P19 artifact with the code bundle files
  code_bundle_sha256 text NULL CHECK (code_bundle_sha256 ~ '^[0-9a-f]{64}$'),
  code_files jsonb NOT NULL DEFAULT '[]',          -- [{path, sha256, size}] of that artifact
  model_refs uuid[] NOT NULL DEFAULT '{}',         -- model versions the policy reads
  notes text NOT NULL DEFAULT '' CHECK (char_length(notes) <= 2000),
  test_summary jsonb NULL,                         -- written by the REWARD_PREVIEW test run
  regression jsonb NULL,                           -- written by the regression run
  exec_sha256 text NULL CHECK (exec_sha256 ~ '^[0-9a-f]{64}$'), -- bundle hash the sandbox reported
  test_job_id uuid NULL,                           -- the test job the version waits for
  created_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz NULL,
  deprecated_at timestamptz NULL,
  CONSTRAINT reward_versions_number UNIQUE (reward_id, version_no),
  CONSTRAINT reward_versions_content UNIQUE (reward_id, content_sha256),
  CHECK ((code_artifact_id IS NULL) = (code_bundle_sha256 IS NULL))
);
CREATE INDEX reward_versions_reward ON reward_versions (reward_id, version_no DESC);
CREATE INDEX reward_versions_test_job ON reward_versions (test_job_id) WHERE test_job_id IS NOT NULL;

-- Test cases are part of a version's content (the publish gate runs them).
CREATE TABLE reward_test_cases (
  version_id uuid NOT NULL REFERENCES reward_versions(id),
  org_id uuid NOT NULL,
  position integer NOT NULL CHECK (position >= 0),
  name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 200),
  sample jsonb NOT NULL,                           -- prompt, completion, reference, …
  expect jsonb NOT NULL,                           -- total / components / flags / status
  last_result jsonb NULL,                          -- the latest test run's outcome
  PRIMARY KEY (version_id, position)
);

-- One row per REWARD_PREVIEW job: a test run, a preview, a regression or a comparison.
-- The completion verifier sets READY (with the results) or INVALID (with the reason).
CREATE TABLE reward_reports (
  id uuid PRIMARY KEY,
  org_id uuid NOT NULL,
  project_id uuid NOT NULL,
  version_id uuid NOT NULL REFERENCES reward_versions(id),
  other_version_id uuid NULL REFERENCES reward_versions(id), -- regression baseline / compare
  mode text NOT NULL CHECK (mode IN ('test', 'preview', 'regression', 'compare')),
  job_id uuid NULL UNIQUE,
  state text NOT NULL CHECK (state IN ('PENDING', 'READY', 'INVALID')),
  request jsonb NOT NULL DEFAULT '{}',
  results jsonb NULL,
  reason text NULL,
  artifact_id uuid NULL,
  created_by text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz NULL
);
CREATE INDEX reward_reports_version ON reward_reports (version_id, created_at DESC);

-- Content never changes; a PUBLISHED version only becomes DEPRECATED.
CREATE FUNCTION reward_versions_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.state IN ('PUBLISHED', 'DEPRECATED') THEN
      RAISE EXCEPTION 'reward version % is published and can''t be deleted', OLD.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF (NEW.id, NEW.org_id, NEW.project_id, NEW.reward_id, NEW.version_no, NEW.policy,
      NEW.content_sha256, NEW.hash_inputs, NEW.sandbox_tier, NEW.code_artifact_id,
      NEW.code_bundle_sha256, NEW.code_files, NEW.model_refs, NEW.notes, NEW.created_by,
      NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.org_id, OLD.project_id, OLD.reward_id, OLD.version_no, OLD.policy,
      OLD.content_sha256, OLD.hash_inputs, OLD.sandbox_tier, OLD.code_artifact_id,
      OLD.code_bundle_sha256, OLD.code_files, OLD.model_refs, OLD.notes, OLD.created_by,
      OLD.created_at) THEN
    RAISE EXCEPTION 'reward version % content is immutable; create a new version', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.state IN ('PUBLISHED', 'DEPRECATED') THEN
    IF NEW.state NOT IN ('PUBLISHED', 'DEPRECATED')
       OR (OLD.state = 'DEPRECATED' AND NEW.state <> 'DEPRECATED')
       OR (NEW.test_summary, NEW.regression, NEW.exec_sha256, NEW.test_job_id, NEW.published_at)
          IS DISTINCT FROM
          (OLD.test_summary, OLD.regression, OLD.exec_sha256, OLD.test_job_id, OLD.published_at) THEN
      RAISE EXCEPTION 'reward version % is published; only deprecating it is allowed', OLD.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER reward_versions_guard BEFORE UPDATE OR DELETE ON reward_versions
  FOR EACH ROW EXECUTE FUNCTION reward_versions_guard();

-- A case's content never changes; its result is frozen once the version is published.
CREATE FUNCTION reward_test_cases_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  st text;
BEGIN
  SELECT state INTO st FROM reward_versions WHERE id = OLD.version_id;
  IF TG_OP = 'DELETE' THEN
    IF st IN ('PUBLISHED', 'DEPRECATED') THEN
      RAISE EXCEPTION 'test cases of published reward version % can''t be deleted', OLD.version_id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN OLD;
  END IF;
  IF (NEW.version_id, NEW.org_id, NEW.position, NEW.name, NEW.sample, NEW.expect)
     IS DISTINCT FROM (OLD.version_id, OLD.org_id, OLD.position, OLD.name, OLD.sample, OLD.expect)
     OR (st IN ('PUBLISHED', 'DEPRECATED') AND NEW.last_result IS DISTINCT FROM OLD.last_result) THEN
    RAISE EXCEPTION 'test case % of reward version % is immutable', OLD.position, OLD.version_id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER reward_test_cases_guard BEFORE UPDATE OR DELETE ON reward_test_cases
  FOR EACH ROW EXECUTE FUNCTION reward_test_cases_guard();
